  -- Lesson 8: Modal Verbs — can, could, may, should, must

  values (v_part_1, 'Modal Verbs — can, could, may, should, must', 'lesson-08', 'Lesson 8 from English Foundation.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"পারা, উচিত, অবশ্যই — এবং ভদ্রভাবে অনুরোধ করা"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🎯 এই Lesson শেষে তুমি যা পারবে"}]},{"type":"paragraph","content":[{"type":"text","text":"১. \"আমি পারি / আমার উচিত / আমাকে অবশ্যই\" — এই ধরনের বাক্য বলতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. ভদ্রভাবে অনুমতি চাইতে ও অনুরোধ করতে পারবে (May I…? Could you…?)।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. must ও have to-এর পার্থক্য বুঝবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. mustn''t আর don''t have to — এই দুটোর ভয়ংকর পার্থক্য জানবে (একটা নিষেধ, আরেকটা ছাড়)।"}]},{"type":"paragraph","content":[{"type":"text","text":"৫. Modal-এর একটাই সোনার নিয়ম শিখবে, যা সব modal-এ খাটে।"}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🔄 শুরুর আগে — Lesson 7 ঝালাই করো"}]},{"type":"paragraph","content":[{"type":"text","text":"১. \"eat\"-এর V3?"}]},{"type":"paragraph","content":[{"type":"text","text":"২. He ____ gone to Dhaka. (have/has)"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. I have lived here ____ ten years. (since/for)"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. ইংরেজি করো: আমি তাকে গতকাল দেখেছি। উত্তর:"}]},{"type":"paragraph","content":[{"type":"text","text":"1. eaten"}]},{"type":"paragraph","content":[{"type":"text","text":"2. has"}]},{"type":"paragraph","content":[{"type":"text","text":"3. for"}]},{"type":"paragraph","content":[{"type":"text","text":"4. I saw him yesterday."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ১ — Modal Verb কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"যে শব্দগুলো মূল verb-এর আগে বসে সামর্থ্য, অনুমতি, উপদেশ বা বাধ্যতা বোঝায়, তাদের Modal Verb বলে। ইংরেজিতে ভদ্রভাবে কথা বলার পুরো ব্যাপারটাই এই শব্দগুলোর উপর দাঁড়িয়ে।"}]},{"type":"paragraph","content":[{"type":"text","text":"Subject  +  Modal  +  Verb (মূল রূপ)"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🔑 সোনার নিয়ম — সব Modal-এ একই"}]},{"type":"paragraph","content":[{"type":"text","text":"১. Modal-এর পরে verb সবসময় মূল রূপে → He can go.  (❌ He can goes / can going / can to go)"}]},{"type":"paragraph","content":[{"type":"text","text":"২. He/She/It-এর জন্য modal-এ s বসে না → ❌ He cans"}]},{"type":"paragraph","content":[{"type":"text","text":"✅ He can"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. Negative-এ do/does লাগে না → ❌ He doesn''t can"}]},{"type":"paragraph","content":[{"type":"text","text":"✅ He can''t"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. প্রশ্নে modal-ই সামনে যায় → Can you help me?"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১.১ ৬টি প্রধান Modal — উচ্চারণসহ"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Modal"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বাংলা উচ্চারণ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"IPA"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"অর্থ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"can"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ক্যান"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"/kæn/"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"পারা (সামর্থ্য / অনু